package com.casystem.onboarding.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
@Service public class TokenService{private final byte[] secret;public TokenService(@Value("${app.jwt-secret}")String s){secret=s.getBytes(StandardCharsets.UTF_8);}private String b64(byte[] b){return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private byte[] sign(String s){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));return m.doFinal(s.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}public String create(Long id,String email){long exp=Instant.now().plusSeconds(8*3600).getEpochSecond();String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));String p=b64(("{\"sub\":\""+id+"\",\"email\":\""+email.replace("\"","")+"\",\"exp\":"+exp+"}").getBytes(StandardCharsets.UTF_8));String hp=h+"."+p;return hp+"."+b64(sign(hp));}public Long userId(String auth){try{if(auth==null||!auth.startsWith("Bearer "))throw new SecurityException("Token requerido");String t=auth.substring(7);String[] a=t.split("\\.");if(a.length!=3)throw new SecurityException("Token inválido");byte[] signature=Base64.getUrlDecoder().decode(a[2]);if(!java.security.MessageDigest.isEqual(sign(a[0]+"."+a[1]),signature))throw new SecurityException("Token inválido");String json=new String(Base64.getUrlDecoder().decode(a[1]),StandardCharsets.UTF_8);long exp=Long.parseLong(json.replaceAll(".*\\\"exp\\\":([0-9]+).*","$1"));if(Instant.now().getEpochSecond()>exp)throw new SecurityException("Token expirado");return Long.parseLong(json.replaceAll(".*\\\"sub\\\":\\\"([0-9]+)\\\".*","$1"));}catch(SecurityException e){throw e;}catch(Exception e){throw new SecurityException("Token inválido");}}}
